numbers = [10, 20, 30]

for number in numbers:
    print(number)

# Conceptually similar to:
iterator = iter(numbers)
while True:
    try:
        number = next(iterator)
        print(number)
    except StopIteration:
        break

class Count:
    def __init__(self, limit):
        self.current = 1
        self.limit = limit

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.limit:
            raise StopIteration
        value = self.current
        self.current += 1
        return value

counter = Count(3)
print(next(counter))
print(next(counter))
print(next(counter))

class EvenNumbers:
    def __init__(self, limit):
        self.current = 0
        self.limit = limit

    def __iter__(self):
        return self

    def __next__(self):
        if self.current > self.limit:
            raise StopIteration
        value = self.current
        self.current += 2
        return value

for number in EvenNumbers(6):
    print(number)

def normal():
    return [1, 2, 3]

def generate():
    for i in range(1, 4):
        yield i

result = normal()
generator = generate()

print(result)
print(generator)
print(list(generator))

def generate_numbers(n):
    for i in range(n):
        yield i

generator = generate_numbers(1000000)

print(next(generator))
print(next(generator))

def numbers():
    yield from [1, 2, 3]
    yield from [4, 5]

for number in numbers():
    print(number)
